        glow: on ? "0 0 16px color-mix(in srgb, var(--dusk-a-500) 24%, transparent)" : "none",
        dot: m.ramp, dotOpacity: on ? "1" : "0.5",
        labelColor: on ? "var(--dusk-a-200)" : "color-mix(in srgb, var(--color-text) 42%, transparent)",
      };
    });
    const words = st.draftText.trim() ? st.draftText.trim().split(/\s+/).filter(Boolean).length : 0;
    const canSave = !!st.draftMood || !!st.draftText.trim();
    const touched = !!(st.draftPhotos || st.draftTags.length || st.draftMood || st.draftText);
    const allTagDefs = TAG_DEFS.concat(st.customTags.map(t => ({ key: t.key, ru: t.label, icon: ICONS.custom })));
    const selLabels = st.draftTags.map(k => this.tagLabel(k));
    const isDiary = st.tab === "diary", isPlan = st.tab === "plan", isEvents = st.tab === "events";
    const tabBg = (on) => on ? "color-mix(in srgb, var(--dusk-a-500) 18%, transparent)" : "transparent";
    const tabColor = (on) => on ? "var(--dusk-a-200)" : "color-mix(in srgb, var(--color-text) 52%, transparent)";

    return {
      kb: st.screen === "compose" && isDiary && st.mode === "write",
      weekdays: wd,
      monthLabel: MONTHS[st.m] + " " + st.y,
      cells: this.buildCells(),
      statsLine: this.monthStats(),
      streakLabel: streak + " " + ruPlural(streak, W_NIGHTS) + " подряд",
      prevMonth: () => this.shiftMonth(-1),
      nextMonth: () => this.shiftMonth(1),
      goToday: this.goToday,
      openDay: this.openDay, closeDay: this.closeDay,
      openComposeDiary: () => this.openCompose("diary"),
      openComposeEvents: () => this.openCompose("events"),
      openComposePlan: () => this.openCompose("plan"),
      closeCompose: this.closeCompose,
      dayAnim: st.dayAnim, composeAnim: st.composeAnim,
      toast: { anim: st.toastAnim, text: st.toastText },
      onType: this.onType, addPhoto: this.addPhoto, save: this.save,
      sel: {
        dateLabel: today ? "Сегодня, " + p.d + " " + MONTHS_GEN[p.m] : dayLabel,
        moodLabel: en ? mood.l : fut ? "впереди" : "нет записи",
        moodColorText: en ? "var(--dusk-a-300)" : "color-mix(in srgb, var(--color-text) 34%, transparent)",
        hasDiary: !!en, noDiary: !en,
        excerpt: en ? (en.text[0].length > 132 ? en.text[0].slice(0, 132).trim() + "…" : en.text[0]) : "",
        tags: en ? en.tags.map(t => ({ l: this.tagLabel(t) })) : [],
        photos: en ? en.photos.map(l => ({ l: l })) : [],
        diaryEmptyLine: fut ? "Ещё впереди." : today ? "Пока ничего не записано." : "Записи нет.",
        openWrite: () => this.openCompose("diary"),
        hasEvents: eventsList.length > 0, noEvents: eventsList.length === 0,
        events: this.eventRows(st.sel, false), addEvent: () => this.openCompose("events"),
        hasPlan: planList.length > 0, noPlan: planList.length === 0,
        planOpen: st.planOpen, caretRot: st.planOpen ? "90deg" : "0deg",
        planSummary: planStats.summary, plan: this.planRows(st.sel, false),
        addPlan: () => this.openCompose("plan"),
        togglePlanOpen: () => this.setState({ planOpen: !st.planOpen }),
        stop: (e) => {},
      },
      day: {
        title: dayLabel,
        meta: en ? "запись в " + en.at + " · " + en.words + " " + ruPlural(en.words, W_WORDS) : "без дневниковой записи",
        hasDiary: !!en,
        moodLine: en ? MOOD_LINE[en.mood] : "Настроение не отмечено.",
        moods: MOODS.map(m => {
          const on = !!en && en.mood === m.k;
          return {
            bg: on ? "color-mix(in srgb, " + m.ramp + " 22%, transparent)" : "color-mix(in srgb, var(--color-surface) 50%, transparent)",
            border: on ? "var(--dusk-a-500)" : "transparent",
            glow: on ? "0 0 14px color-mix(in srgb, var(--dusk-a-500) 22%, transparent)" : "none",
            dot: m.ramp, dotOpacity: on ? "1" : "0.32",
          };
        }),
        photos: en ? en.photos.map(l => ({ l: l })) : [],
        text: en ? en.text.map(t => ({ t: t })) : [],
        tags: en ? en.tags.map(t => ({ l: this.tagLabel(t) })) : [],
        hasEvents: eventsList.length > 0, noEvents: eventsList.length === 0, events: this.eventRows(st.sel, false),
        planSummary: planStats.summary, plan: this.planRows(st.sel, false), noPlan: planList.length === 0,
      },
      draft: {
        title: today ? "Сегодня вечером · " + p.d + " " + MONTHS_GEN[p.m] : dayLabel,
        subtitle: isPlan ? "Что по плану?" : isEvents ? "Что произошло?" : "Как прошёл день?",
        isDiaryTab: isDiary, isPlanTab: isPlan, isEventsTab: isEvents, notDiaryTab: !isDiary,
        setTabDiary: () => this.setTab("diary"), setTabPlan: () => this.setTab("plan"), setTabEvents: () => this.setTab("events"),
        diaryTabBg: tabBg(isDiary), diaryTabColor: tabColor(isDiary),
        planTabBg: tabBg(isPlan), planTabColor: tabColor(isPlan),
        eventsTabBg: tabBg(isEvents), eventsTabColor: tabColor(isEvents),
        isQuick: st.mode === "quick", isWrite: st.mode === "write",
        setQuick: () => this.setState({ mode: "quick" }), setWrite: () => this.setState({ mode: "write" }),
        quickBg: st.mode === "quick" ? "color-mix(in srgb, var(--dusk-a-500) 18%, transparent)" : "transparent",
        quickColor: st.mode === "quick" ? "var(--dusk-a-200)" : "color-mix(in srgb, var(--color-text) 52%, transparent)",
        writeBg: st.mode === "write" ? "color-mix(in srgb, var(--dusk-a-500) 18%, transparent)" : "transparent",
        writeColor: st.mode === "write" ? "var(--dusk-a-200)" : "color-mix(in srgb, var(--color-text) 52%, transparent)",
        moodTiles: moodTiles,
        chips: allTagDefs.map(def => {
          const on = st.draftTags.indexOf(def.key) >= 0;
          return {
            label: def.ru, iconPath: def.icon, onClick: () => this.toggleTag(def.key),
            bg: on ? "color-mix(in srgb, var(--dusk-a-500) 20%, transparent)" : "color-mix(in srgb, var(--color-surface) 55%, transparent)",
            border: on ? "var(--dusk-a-500)" : "var(--color-neutral-800)",
            color: on ? "var(--dusk-a-300)" : "color-mix(in srgb, var(--color-text) 50%, transparent)",
          };
        }),
        addingTag: st.addingTag, newTagText: st.newTagText,
        startAddTag: this.startAddTag, cancelAddTag: this.cancelAddTag,
        confirmAddTag: this.confirmAddTag, onNewTagType: this.onNewTagType, onNewTagKey: this.onNewTagKey,
        tagSummary: selLabels.length ? ("Сегодня: " + selLabels.join(", ")) : "Пока ничего не выбрано",
        photos: Array.from({ length: st.draftPhotos }, (_, i) => ({ l: "фото " + (i + 1) })),
        prompt: PROMPTS[p.d % PROMPTS.length],
        text: st.draftText,
        wordCount: words + " " + ruPlural(words, W_WORDS),
        moodNote: st.draftMood ? this.mood(st.draftMood).l : "настроение не выбрано",
        hint: canSave ? "Запись сохранится только на этом телефоне." : "Выберите настроение или напишите что-нибудь.",
        saveLabel: touched ? "Сохранить день" : "Сохранить",
        saveBorder: canSave ? "var(--dusk-a-500)" : "var(--color-neutral-800)",
        saveColor: canSave ? "var(--dusk-a-300)" : "color-mix(in srgb, var(--color-text) 30%, transparent)",
        planRows: this.planRows(st.sel, true), noPlanRows: planList.length === 0,
        newPlanText: st.newPlanText, onNewPlanType: this.onNewPlanType, onNewPlanKey: this.onNewPlanKey, addPlanItem: this.addPlanItem,
        eventRows: this.eventRows(st.sel, true), noEventRows: eventsList.length === 0,
        newEventTitle: st.newEventTitle, newEventTime: st.newEventTime,
        onNewEventTitleType: this.onNewEventTitleType, onNewEventTimeType: this.onNewEventTimeType, onNewEventKey: this.onNewEventKey,
        addEvent: this.addEvent,
        eventTypeTiles: EVENT_TYPES.map(t => {
          const on = st.newEventType === t.key;
          return {
            label: t.ru, iconPath: t.icon, onClick: () => this.setNewEventType(t.key),
            bg: on ? "color-mix(in srgb, var(--dusk-a-500) 20%, transparent)" : "color-mix(in srgb, var(--color-surface) 55%, transparent)",
            border: on ? "var(--dusk-a-500)" : "var(--color-neutral-800)",
            color: on ? "var(--dusk-a-300)" : "color-mix(in srgb, var(--color-text) 50%, transparent)",
          };
        }),
      },
    };
  }
}
